static int compare_ints(const void *left, const void *right) {
    int a = *(const int *)left, b = *(const int *)right;
    return (a > b) - (a < b);
}

int main(void) {
    char input[65536];
    if (!fgets(input, sizeof input, stdin)) return 2;
    int values[8192]; size_t count = 0;
    size_t length = strcspn(input, "\r\n");
    input[length] = '\0';
