    while (*cursor == ' ' || *cursor == '\t') cursor++;
    if (*cursor) {
        while (*cursor) {
            char *comma = strchr(cursor, ',');
            char *finish = comma ? comma : cursor + strlen(cursor);
            *finish = '\0';
            while (*cursor == ' ' || *cursor == '\t') cursor++;
            errno = 0; char *end = NULL; long value = strtol(cursor, &end, 10);
